// TimestampNow writes the current time in ISO 8601, for a command's
// timestamp, to out_timestamp.
//
// C: otio_ext_ori_timestamp_now
func TimestampNow() (string, error) {
	var outTimestamp C.OtioBuffer
	var cError C.OtioBuffer
	if status := C.otio_ext_ori_timestamp_now(&outTimestamp, &cError); status != C.OTIO_STATUS_OK {
		return "", statusError(status, cError)
	}
	defer C.otio_buffer_free(outTimestamp)
	return goText(outTimestamp), nil
}

// statusError turns a status into the otio package's error, with the message
// the same call wrote beside it, as that package does for its own calls. It
// releases the message, so each one is handed here once.
func statusError(status C.OtioStatus, message C.OtioBuffer) error {
	var text string
	if message.data != nil {
		text = C.GoStringN(message.data, C.int(message.len))
	}
	C.otio_buffer_free(message)
	if status == C.OTIO_STATUS_OK {
		return nil
	}
	return &otio.Error{Status: otio.Status(status), Message: text}
}

// goText copies a buffer of text out of the library.
func goText(buffer C.OtioBuffer) string {
	if buffer.data == nil {
		return ""
	}
	return C.GoStringN(buffer.data, C.int(buffer.len))
}
